// Supabase Edge Function: accept-manager-invite
//
// Public endpoint (no Authorization header). A manager who received an
// invite link from the property owner lands on /join?type=manager&token=...
// and sets their own password here. Mirrors accept-tenant-invite exactly,
// for managers instead of tenants.
//
// Security: the only thing that authorizes this call is knowing a valid,
// unexpired invite_token — generated by the owner via
// fn_generate_manager_invite (SECURITY DEFINER, checks
// managers.owner_id = auth.uid() before minting one).

// deno-lint-ignore-file no-explicit-any
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2.112.3'
const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
  'Access-Control-Allow-Methods': 'POST, OPTIONS',
}
function jsonResponse(body: unknown, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, 'Content-Type': 'application/json' },
  })
}

const SUPABASE_URL = Deno.env.get('SUPABASE_URL')!
const SERVICE_ROLE_KEY = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/

function isEmailIdentifier(identifier: string): boolean {
  return EMAIL_RE.test(identifier.trim())
}

function normalizePhoneIdentifier(identifier: string): string {
  const trimmed = identifier.trim()
  if (trimmed.startsWith('+')) return trimmed.replace(/[\s-]/g, '')
  const digits = trimmed.replace(/\D/g, '')
  if (digits.length === 10) return `+91${digits}`
  return `+${digits}`
}

interface Body {
  token: string
  identifier: string
  password: string
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders })
  if (req.method !== 'POST') return jsonResponse({ error: 'Method not allowed' }, 405)

  try {
    const body = (await req.json().catch(() => null)) as Body | null
    if (!body?.token || !body?.identifier || !body?.password) {
      return jsonResponse({ error: 'token, identifier and password are required' }, 400)
    }
    if (body.password.length < 6) {
      return jsonResponse({ error: 'Password must be at least 6 characters.' }, 400)
    }

    const admin = createClient(SUPABASE_URL, SERVICE_ROLE_KEY)

    const { data: manager, error: mErr } = await admin
      .from('managers')
      .select('id, owner_id, full_name, profile_id, invite_token_expires_at')
      .eq('invite_token', body.token)
      .maybeSingle()
    if (mErr) return jsonResponse({ error: mErr.message }, 500)
    if (!manager) return jsonResponse({ error: 'This invite link is invalid.' }, 404)
    if ((manager as any).profile_id) return jsonResponse({ error: 'This invite link has already been used.' }, 400)
    const expiresAt = (manager as any).invite_token_expires_at
    if (!expiresAt || new Date(expiresAt).getTime() < Date.now()) {
      return jsonResponse({ error: 'This invite link has expired. Please ask the property owner to send a new one.' }, 400)
    }

    const isEmail = isEmailIdentifier(body.identifier)
    const identifier = isEmail ? body.identifier.trim().toLowerCase() : normalizePhoneIdentifier(body.identifier)

    const { data: created, error: createErr } = await admin.auth.admin.createUser(
      isEmail
        ? { email: identifier, password: body.password, email_confirm: true }
        : { phone: identifier, password: body.password, phone_confirm: true }
    )
    if (createErr || !created?.user) {
      return jsonResponse({ error: createErr?.message ?? 'Could not create the login.' }, 400)
    }

    const newUserId = created.user.id

    const { error: profileErr } = await admin.from('profiles').upsert({
      id: newUserId,
      role: 'manager',
      full_name: (manager as any).full_name,
      email: isEmail ? identifier : null,
      phone: isEmail ? null : identifier,
      owner_id: (manager as any).owner_id,
    })
    if (profileErr) return jsonResponse({ error: `Login created but profile setup failed: ${profileErr.message}` }, 500)

    const { error: linkErr } = await admin
      .from('managers')
      .update({ profile_id: newUserId, invite_token: null, invite_token_expires_at: null })
      .eq('id', (manager as any).id)
    if (linkErr) return jsonResponse({ error: `Login created but manager link failed: ${linkErr.message}` }, 500)

    return jsonResponse({ success: true, identifier, isEmail })
  } catch (err) {
    return jsonResponse({ error: (err as Error).message ?? 'Unexpected error' }, 500)
  }
})
